WITH matched_keys AS (SELECT page, event_type FROM web_events EXCEPT ALL SELECT page, event_type FROM web_events WHERE session_id = 13), kept_rows AS (SELECT s.* FROM web_events s INNER JOIN matched_keys k ON s.page = k.page AND s.event_type = k.event_type) SELECT s.id, s.session_id, s.event_type, s.page, s.duration_sec, (SELECT AVG(w2.duration_sec) FROM web_events w2 WHERE w2.session_id = s.session_id) AS avg_web_event_duration_sec FROM kept_rows s ORDER BY duration_sec DESC NULLS FIRST;
